UPDATE campus_department
parent_id = #{parentId}, department_name = #{departmentName}, department_code = #{departmentCode}, department_type = #{departmentType}, leader_user_id = #{leaderUserId}, contact_phone = #{contactPhone}, sort_no = #{sortNo}, status = #{status}, deleted = #{deleted}, update_user_id = #{updateUserId}
